CREATE TABLE IF NOT EXISTS accounts."InsurancePolicies" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL,
    "Kind" integer NOT NULL DEFAULT 0,
    "Name" text NOT NULL,
    "Insurer" text NULL,
    "PolicyNumber" text NULL,
    "InsuredPeople" text NULL,
    "Nominee" text NULL,
    "SumAssured" numeric(18,2) NOT NULL DEFAULT 0,
    "Premium" numeric(18,2) NOT NULL DEFAULT 0,
    "PremiumFrequency" integer NOT NULL DEFAULT 3,
    "StartDate" date NULL,
    "NextDueDate" date NULL,
    "ExpiryDate" date NULL,
    "WaitingPeriodEnds" date NULL,
    "Notes" text NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT now(),
    "UpdatedAt" timestamp with time zone NULL,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL
);
CREATE INDEX IF NOT EXISTS "IX_InsurancePolicies_UserId" ON accounts."InsurancePolicies" ("UserId");
